include <robotics.scad>
// Origin: board centre, bottom face. +Y = clamp/top edge, -Y = tripod tab edge.
W = 38; T = 1.4; hole_d = 2.5; hole_off = 15;
notch_d = 5.71;              // matches rear-lip height on drawing
notch_top_hw = 11.55;        // scaled from drawing
notch_edge_hw = 10.92;       // scaled from drawing
difference() {
  linear_extrude(T) offset(r=1) offset(delta=-1) square(W, center=true);
  for (x=[-1,1], y=[-1,1]) translate([x*hole_off, y*hole_off, -1]) cylinder(d=hole_d, h=T+2, $fn=32);
  translate([0,0,-1]) linear_extrude(T+2)
    polygon([[-notch_edge_hw,-W/2-0.1],[notch_edge_hw,-W/2-0.1],[notch_top_hw,-W/2+notch_d],[-notch_top_hw,-W/2+notch_d]]);
}

include <robotics.scad>
// Origin: board centre at PCB bottom face (z=0). Lens axis = +Z.
pcb_t = 1.4; body_h = 10.35; top = pcb_t + body_h;      // 11.75
body_d = 34.4;          // scaled from side view (not dimensioned)
bore_d = 22.4;
tab_w = 13.97; tab_reach = 11.36;  // reach below board edge scaled
lip_h = 5.71; lip_t = 2.75;
edge = -19;
ntop = 11.55; nedge = 10.92; flare_y = edge - 4.7;     // scaled
clamp_w = 10.16; clamp_d = 5.02; slit = 0.8; clamp_top = 19 + 2.5; clamp_bot = 16.0;
tripod_d = 6.35; tripod_depth = 6; tripod_z = top - 7.62/2;   // assumed centred in 7.62 block

notch_poly = [[-nedge,edge],[nedge,edge],[ntop,edge+lip_h],[-ntop,edge+lip_h]];
tab_poly = [[-nedge,edge+0.01],[nedge,edge+0.01],[tab_w/2,flare_y],[tab_w/2,edge-tab_reach],
            [-tab_w/2,edge-tab_reach],[-tab_w/2,flare_y]];
$fn=96;
difference() {
  union() {
    translate([0,0,pcb_t]) cylinder(d=body_d, h=body_h);
    // fill in PCB notch + rear lip behind the PCB
    translate([0,0,-lip_t]) linear_extrude(lip_t + top) polygon(notch_poly);
    // tripod tab below board edge, PCB back plane to mount face
    linear_extrude(top) polygon(tab_poly);
    // top split clamp ear
    translate([-clamp_w/2, clamp_bot, top-clamp_d]) cube([clamp_w, clamp_top-clamp_bot, clamp_d]);
  }
  translate([0,0,-5]) cylinder(d=bore_d, h=30);
  translate([-slit/2, 12, top-clamp_d-0.1]) cube([slit, 12, clamp_d+0.2]);
  translate([0, edge-tab_reach-0.1, tripod_z]) rotate([-90,0,0]) cylinder(d=tripod_d, h=tripod_depth, $fn=48);
}

